{
  "manifest_version": 3,
  "name": "Focus Blocker",
  "description": "Blocks distracting websites while you should be focusing.",
  "version": "0.1.0",

  "permissions": [
    "storage",
    "declarativeNetRequestWithHostAccess"
  ],

  "host_permissions": [
    "*://*.youtube.com/*",
    "*://youtube.com/*",

    "*://*.instagram.com/*",
    "*://instagram.com/*",

    "*://*.netflix.com/*",
    "*://netflix.com/*"
  ],

  "background": {
    "service_worker": "service-worker.js"
  },

  "action": {
    "default_popup": "popup/popup.html"
  },

  "web_accessible_resources": [
    {
      "resources": [
        "blocked/blocked.html",
        "blocked/blocked.css"
      ],
      "matches": [
        "<all_urls>"
      ]
    }
  ]
}
